`createDockState` returns a fresh state with `visible: true` and actions ordered as `dismiss`, then `enroll`. The dismiss action has label `Close`; the enroll action has label `Enroll` and target `/enroll`. Each call and every nested action must be independently allocated.

`reduceDock` must not mutate or alias its input. Command `dismiss` returns a fresh state with `visible: false`; command `show` returns one with `visible: true`; command `activate-enroll` returns the same visibility and sets `lastTarget` to `/enroll`. Existing actions retain their order and values through reductions but are deeply copied. Unknown commands throw `RangeError`.

Known-bad source:

export type DockAction = {
  id: "dismiss" | "enroll";
  label: string;
  target?: string;
};

export type DockState = {
  visible: boolean;
  actions: DockAction[];
  lastTarget?: string;
};

export type DockCommand = "dismiss" | "show" | "activate-enroll";

export function createDockState(): DockState {
  return {
    visible: true,
    actions: [
      { id: "dismiss", label: "Close" },
      { id: "enroll", label: "Enroll", target: "/enroll" }
    ]
  };
}

export function reduceDock(state: DockState, command: DockCommand): DockState {
  const copy: DockState = {
    ...state,
    actions: state.actions.map((action) => ({ ...action }))
  };
  if (command === "dismiss") return { ...copy, visible: true };
  if (command === "show") return { ...copy, visible: true };
  if (command === "activate-enroll") return { ...copy, lastTarget: "/enroll" };
  throw new RangeError("unknown command");
}

