import { DockState, createDockState, reduceDock } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function deepEqual(actual: unknown, expected: unknown, message: string): void {
  assert(JSON.stringify(actual) === JSON.stringify(expected), message);
}

const expected = {
  visible: true,
  actions: [
    { id: 'dismiss', label: 'Close' },
    { id: 'enroll', label: 'Enroll', target: '/enroll' }
  ]
};

const first = createDockState();
deepEqual(first, expected, 'initial dock state must match the specified descriptor');
const second = createDockState();
assert(first !== second, 'each initial state must be fresh');
assert(first.actions !== second.actions, 'initial action arrays must be fresh');
assert(first.actions[0] !== second.actions[0] && first.actions[1] !== second.actions[1], 'every initial action must be fresh');
first.actions[0].label = 'Changed';
first.actions.push({ id: 'dismiss', label: 'Injected' });
deepEqual(second, expected, 'mutating one initial state must not affect later states');

const state: DockState = {
  visible: true,
  actions: [
    { id: 'dismiss', label: 'Close' },
    { id: 'enroll', label: 'Enroll', target: '/custom-preserved' }
  ],
  lastTarget: '/old'
};
const snapshot = JSON.stringify(state);
const dismissed = reduceDock(state, 'dismiss');
assert(dismissed.visible === false, 'dismiss must hide the dock');
assert(JSON.stringify(state) === snapshot, 'reduction must not mutate input state');
assert(dismissed !== state && dismissed.actions !== state.actions, 'dismiss must return fresh state and action array');
assert(dismissed.actions[0] !== state.actions[0] && dismissed.actions[1] !== state.actions[1], 'dismiss must deeply copy actions');
deepEqual(dismissed.actions, state.actions, 'dismiss must preserve existing action order and values');
assert(dismissed.lastTarget === '/old', 'dismiss must retain other state fields');

const shown = reduceDock({ ...state, visible: false }, 'show');
assert(shown.visible === true, 'show must make the dock visible');
deepEqual(shown.actions, state.actions, 'show must preserve actions');

const activated = reduceDock({ ...state, visible: false }, 'activate-enroll');
assert(activated.visible === false, 'activate-enroll must preserve visibility');
assert(activated.lastTarget === '/enroll', 'activate-enroll must set the enrollment target');
deepEqual(activated.actions, state.actions, 'activate-enroll must preserve actions');
assert(activated.actions[0] !== state.actions[0], 'activate-enroll must deeply copy actions');

let unknownError: unknown;
try {
  reduceDock(state, 'unknown' as unknown as 'dismiss');
} catch (error) {
  unknownError = error;
}
assert(unknownError instanceof RangeError, 'unknown commands must throw RangeError');
assert(JSON.stringify(state) === snapshot, 'unknown commands must not mutate input state');

